rules:
@media (prefers-reduced-motion: no-preference) {
  .fx .prose img[loading="lazy"]:not(.is-loaded) { opacity: 0; filter: blur(6px); scale: 0.985; }
  .fx .prose img[loading="lazy"] { transition: opacity .6s var(--ease-out), filter .7s var(--ease-out), scale var(--dur-gentle) var(--spring-gentle); }
}

@media (prefers-reduced-motion: no-preference) {
  .js [data-reveal] { animation-duration: ; animation-timing-function: ; animation-iteration-count: ; animation-direction: ; animation-fill-mode: ; animation-play-state: ; animation-name: ; animation-timeline: ; animation-range-start: ; animation-range-end: ; animation-delay: calc(min(var(--i,0), 12) * 38ms + 90ms); }
  .js [data-reveal="title"] { animation-name: rise-title; }
  .js .page-index [data-reveal] { animation-name: rise-index; animation-duration: 0.2s; animation-timing-function: var(--ease-out); animation-delay: calc(min(var(--i,0), 5) * 8ms); }
}
